<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../services/api'
const route=useRoute(), lessons=ref([]), lesson=ref(null), page=ref(0), source=ref(''),proposal=ref(''),images=ref([]),status=ref(''),job=ref(null)
const number=computed(()=>Number(route.params.lesson||lesson.value?.lesson||0));const total=computed(()=>lesson.value?.last-lesson.value?.first+1||0)
async function load(){lessons.value=(await api.lessons()).lessons||[];lesson.value=lessons.value.find(x=>x.lesson===number.value)||lessons.value[0];if(!lesson.value)return;page.value=Number(route.query.page||lesson.value.first);await render()}
async function render(){if(!lesson.value)return;page.value=Math.max(lesson.value.first,Math.min(page.value,lesson.value.last));status.value='Cargando evidencia…';try{await api.renderLesson(lesson.value.lesson);images.value=(await api.pageImages(lesson.value.lesson,page.value)).images||[];const pad=String(lesson.value.lesson).padStart(2,'0');source.value=await fetch(`/lecciones_originales/L${pad}.xml?v=${Date.now()}`).then(r=>r.ok?r.text():'XML fuente no disponible');proposal.value=await fetch(`/lecciones_propuestas/L${pad}.xml?v=${Date.now()}`).then(r=>r.ok?r.text():'Propuesta aún no generada');status.value='Página lista para revisión.'}catch(e){status.value=e.message}}
async function changeLesson(){lesson.value=lessons.value.find(x=>x.lesson===Number(selected.value));page.value=lesson.value.first;await render()};const selected=ref(0)
async function approve(){try{status.value=(await fetch(`/api/approve-lesson?lesson=${lesson.value.lesson}`,{method:'POST'}).then(r=>r.json())).message||'Lección aprobada.'}catch(e){status.value=e.message}}
onMounted(load);watch(()=>route.params.lesson,load)
</script>
<template><section class="hero"><span class="eyebrow">AUDITORÍA VISUAL</span><h2>Comparación PDF · XML · DTBook</h2><p>Revisa la página del PDF contra la fuente y la propuesta antes de aprobar la lección.</p></section><section v-if="lesson" class="audit-toolbar"><label>Lección<select v-model="selected" @change="changeLesson"><option v-for="item in lessons" :value="item.lesson">L{{String(item.lesson).padStart(2,'0')}} · {{item.status}}</option></select></label><button class="secondary" :disabled="page===lesson.first" @click="page--;render()">← Anterior</button><strong>Página {{page}} de {{lesson.last}}</strong><button class="secondary" :disabled="page===lesson.last" @click="page++;render()">Siguiente →</button><button @click="approve">Aprobar lección</button></section><p class="notice">{{status}}</p><section v-if="lesson" class="audit-grid"><article class="audit-panel"><header><strong>PDF</strong><span>Referencia visual</span></header><img :src="`/auditoria-lecciones/assets/L${String(lesson.lesson).padStart(2,'0')}/page-${String(page-lesson.first+1).padStart(2,'0')}.png`" alt="Página PDF"/></article><article class="audit-panel"><header><strong>XML fuente</strong><span>Solo lectura</span></header><pre>{{source}}</pre></article><article class="audit-panel"><header><strong>DTBook propuesto</strong><span>Solo lectura</span></header><pre>{{proposal}}</pre></article></section><section class="audit-panel image-gallery"><header><strong>Imágenes de la página</strong><span>{{images.length}} detectadas</span></header><div class="image-row"><figure v-for="image in images" :key="image.id||image.src"><img :src="image.url" :alt="image.id||'Imagen detectada'"/><figcaption>{{image.id||image.src}}</figcaption></figure><p v-if="!images.length" class="hint">No hay imágenes referenciadas en esta página.</p></div></section></template>
